//! ANSI output of every Rich style attribute compared with Python Rich 15,
//! using `tests/fixtures/style_ansi.golden` (generated by
//! `scripts/gen_style_ansi_golden.py`).
//!
//! Rich writes all SGR parameters of a style in one escape (`ESC[1;53m`)
//! with attributes before colors; fast-rich writes one escape per color or
//! attribute. Both set the same terminal state, so the test compares the
//! set of SGR parameters, and the exact bytes for single-attribute styles.

use fast_rich::console::{ColorSystem, Console};
use fast_rich::style::Style;
use fast_rich::text::Text;

const GOLDEN: &str = include_str!("fixtures/style_ansi.golden");

fn unhex(hex: &str) -> String {
    let bytes: Vec<u8> = (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect();
    String::from_utf8(bytes).unwrap()
}

fn render(style: Style) -> String {
    let console = Console::capture()
        .width(20)
        .force_color(true)
        .color_system(ColorSystem::TrueColor);
    console.print_renderable(&Text::styled("x", style));
    console.get_captured_output()
}

/// SGR parameters of the escapes before the first printed character.
fn leading_sgr(output: &str) -> Vec<String> {
    let head = &output[..output.find('x').expect("no text in output")];
    let mut params: Vec<String> = head
        .split("\x1b[")
        .filter_map(|esc| esc.strip_suffix('m'))
        .flat_map(|p| p.split(';').map(str::to_string).collect::<Vec<_>>())
        .collect();
    params.sort();
    params
}

#[test]
fn style_sgr_codes_match_rich() {
    let mut count = 0;
    let mut failures = Vec::new();
    for line in GOLDEN.lines().filter(|l| !l.starts_with("# ")) {
        let f: Vec<&str> = line.split(' ').collect();
        let name = f[0].replace('+', " ");
        let rich_out = unhex(f[2]);
        let mut want: Vec<String> = f[1].split(';').map(str::to_string).collect();
        want.sort();
        let ours = render(Style::parse(&name));
        if leading_sgr(&ours) != want {
            failures.push(format!("{name}: {ours:?} != rich {rich_out:?}"));
        } else if !f[1].contains(';') && ours != rich_out {
            failures.push(format!("{name}: bytes {ours:?} != rich {rich_out:?}"));
        }
        count += 1;
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    assert_eq!(count, 21);
}

#[test]
fn new_attributes_display_and_combine() {
    let all = Style::parse("blink2 underline2 frame encircle overline");
    assert_eq!(all.to_string(), "blink2 underline2 frame encircle overline");
    assert_eq!(
        Style::new().overline().combine(&Style::new().frame()),
        Style::parse("overline frame")
    );
    assert!(!Style::new().encircle().is_empty());
    assert_eq!(Style::parse("o not o"), Style::new());
}
